insert into public.settings (key, value, label, description) values
  ('ppf_brand_name', '"OFJ PPF"'::jsonb, 'PPF brand name', 'Shown on the quotation link, the handover page and the warranty certificate.'),
  ('ppf_warranty_years', '10'::jsonb, 'PPF warranty years', 'The certificate is valid for this many years from the installation date.'),
  ('ppf_warranty_text', to_jsonb('OFJ PPF is warranted against yellowing, cracking, peeling, bubbling and delamination for ten years from the installation date, when the film is cared for as described in the care instructions. The warranty covers the film and its reinstallation; it does not cover damage from accidents, stones, chemicals, abrasion, improper washing or removal by a third party. Valid for the vehicle named on this certificate.'::text), 'PPF warranty wording', 'Printed on the warranty certificate.'),
  ('ppf_care_text', to_jsonb('Wait 7 days before the first wash. Hand wash or touchless only; no automatic brushes. Use pH-neutral shampoo and microfibre only. Remove bird droppings, tree sap and insects as soon as you can. No wax or sealant with petroleum distillates; a PPF-safe sealant is fine. Keep pressure washers 50 cm away and off the film edges.'::text), 'PPF care instructions', 'Shown on the handover page and the certificate, sent with the handover link.'),
  ('ppf_removal_note', to_jsonb('We take great care removing old film, but paint underneath can occasionally lift.'::text), 'Old PPF removal note', 'Shown on the quotation when Old PPF removal is on it; the customer ticks that they understand before approving.'),
  ('bodyshop_final_check_days', '10'::jsonb, 'Final check days after handover', 'The default for the PPF final check visit (7 to 14 days).'),
  ('whatsapp_bodyshop_arrived_template', to_jsonb(E'[make model] ([plate]) has arrived at OFJ Automotive and is in good hands:\n[link]'::text), 'WhatsApp: your car has arrived', 'Sent once, with one photo chosen by the team leader.'),
  ('whatsapp_bodyshop_film_template', to_jsonb(E'Film is going on [make model] ([plate]):\n[link]'::text), 'WhatsApp: film is going on', 'Sent once, with one photo chosen by the team leader.'),
  ('whatsapp_bodyshop_ready_template', to_jsonb(E'[make model] ([plate]) is ready for collection. Your handover page, warranty and care instructions:\n[link]'::text), 'WhatsApp: your car is ready for collection', 'Sent once; the link opens the handover page.'),
  ('whatsapp_final_check_template', to_jsonb('Dear [name], a reminder of the final check of [make model] ([plate]) at OFJ Automotive tomorrow, [date] at [time]. Thank you, [advisor], OFJ Automotive'::text), 'WhatsApp: final check reminder', 'The reminder the day before the PPF final check visit.')
